#!/bin/sh
# Fixture dev server for the production-pass walks. Usage: sh dev-server.sh <port> [extra env assignments...]
P=${1:-4310}; shift
cd "$(dirname "$0")/../../.." || exit 1
env SIDEQUEST_DB_PATH=$PWD/apps/web/data/pp-dev.db SIDEQUEST_SECURE_COOKIES=off ANTHROPIC_API_KEY= GOOGLE_MAPS_API_KEY= SIDEQUEST_GEOCODER_PROVIDER=off SIDEQUEST_PLACE_BACKBONE=off SIDEQUEST_POI_PROVIDER=off SIDEQUEST_ROUTES_PROVIDER=off SIDEQUEST_RESEARCH_PROVIDER=off SIDEQUEST_IMAGERY_PROVIDER=fixture SIDEQUEST_TIMEZONE_PROVIDER=off SIDEQUEST_TRANSIT_PROVIDER= SIDEQUEST_WEATHER_PROVIDER=fixture SIDEQUEST_COMPILER_PROVIDER=fixture SIDEQUEST_COMPOSER_PROVIDER=fixture SIDEQUEST_CLIMATE_PROVIDER=fixture SIDEQUEST_FX_PROVIDER=off SIDEQUEST_DESTINATION_INTERPRETER=fixture SIDEQUEST_BENCHMARK_MODE=fixture SIDEQUEST_ACTION_FENCES=off SIDEQUEST_AUTH_PROVIDER=fixture SIDEQUEST_AUTH_FIXTURE=allow SIDEQUEST_FIXTURES=allow SIDEQUEST_BASE_URL=http://localhost:$P SIDEQUEST_DESTINATION_INDEX_SEED=../../e2e/support/destination-index.ndjson PORT=$P "$@" npm run dev --workspace @sidequest/web
